samples.content:
targetScope = 'local'

param vaultUri string

@secure()
param secretVal string

extension keyvault with {
  vaultUri: vaultUri
}

resource secret 'Secret' = {
  name: 'mysecret'
  value: secretVal
  contentType: 'text/plain'
  tags: {
    environment: 'demo'
  }
}

resource key 'Key' = {
  name: 'mykey'
  keyType: 'RSA'
  keySize: 2048
  keyOps: ['sign', 'verify', 'wrapKey', 'unwrapKey']
  rotationPolicy: {
    expireAfter: 'P90D'
    notifyBeforeExpiry: 'P29D'
    automatic: {
      timeBeforeExpiry: 'P30D'
    }
  }
}

resource contacts 'CertificateContacts' = {
  contacts: [
    {
      email: 'admin@contoso.com'
      name: 'Certificate Admin'
    }
  ]
}

resource cert 'Certificate' = {
  name: 'mycert'
  issuer: {
    name: 'Self'
  }
  key: {
    exportable: true
    keySize: 2048
    keyType: 'RSA'
    reuseKey: true
  }
  secret: {
    contentType: 'application/x-pkcs12'
  }
  lifetimeActions: [
    {
      action: {
        actionType: 'AutoRenew'
      }
      trigger: {
        daysBeforeExpiry: 30
      }
    }
  ]
  x509Properties: {
    ekus: ['1.3.6.1.5.5.7.3.1']
    keyUsage: [
      'cRLSign'
      'dataEncipherment'
      'digitalSignature'
      'keyAgreement'
      'keyCertSign'
      'keyEncipherment'
    ]
    subjectAlternativeNames: {
      dnsNames: ['internal.contoso.com', 'domain.hello.world']
    }
    subject: 'CN=hello-world'
    validityInMonths: 12
  }
}

@description('Use the version-less id to always resolve the current version of the secret.')
output secretUri string = secret.versionlessId

@description('The public half of the generated key, ready to drop into an authorized_keys file.')
output keyPublicKeyOpenSsh string = key.publicKeyOpenSsh

output certificateThumbprint string = cert.thumbprint
output certificateExpires string = cert.certificateAttributes.expires

/*
  Seeds an application's configuration secrets into a Key Vault.

  Demonstrates:
    - declaring many secrets from a single list, using a loop
    - separating non-sensitive metadata from the secret values themselves
    - setting an expiry so that stale secrets are visible to rotation tooling
    - purging on delete, which is what you usually want for a throwaway dev vault
*/

targetScope = 'local'

@description('The URI of the Key Vault to seed, e.g. https://myvault.vault.azure.net/.')
param vaultUri string

@description('The application these secrets belong to. Applied as a tag.')
param application string

@description('Deployment environment. Applied as a tag, and controls whether secrets are purged on delete.')
@allowed(['dev', 'test', 'prod'])
param environment string

@description('Non-sensitive metadata describing each secret.')
param secretDefinitions secretDefinition[]

@description('The secret values, keyed by secret name. Keep these in a key vault reference or a CI secret store rather than in source control.')
@secure()
param secretValues object

@description('Metadata for a single application secret.')
type secretDefinition = {
  @description('The name of the secret in Key Vault.')
  name: string

  @description('The MIME type of the value, e.g. text/plain or application/json.')
  contentType: string

  @description('''
  The UTC expiry, in ISO 8601 format.
  Prefer a fixed date over utcNow(): a value that changes on every run makes the secret look
  like it has drifted, so every deployment would rewrite its metadata.
  ''')
  expiresOn: string
}

extension keyvault with {
  vaultUri: vaultUri

  // Dev vaults are recreated constantly, and soft-deleted secrets block a name from being
  // reused. Purging on delete keeps redeployment frictionless. Never do this in production:
  // it discards your only recovery path.
  purgeOnDelete: environment == 'dev'

  // If a secret was previously deleted but not purged, recover it rather than failing.
  recoverSoftDeleted: true
}

resource applicationSecrets 'Secret' = [
  for definition in secretDefinitions: {
    name: definition.name
    // The value does come from a @secure() parameter, but the linter cannot track that through
    // an index expression, so it has to be told this is intentional.
    #disable-next-line use-secure-value-for-secure-inputs
    value: secretValues[definition.name]
    contentType: definition.contentType
    expiresOn: definition.expiresOn
    tags: {
      application: application
      environment: environment
      managedBy: 'bicep'
    }
  }
]

@description('Version-less URIs for the seeded secrets. Bind applications to these so they always read the current version.')
output secretUris array = [
  for (definition, index) in secretDefinitions: {
    name: definition.name
    uri: applicationSecrets[index].versionlessId
  }
]

/*
  The three ways to get a certificate into Key Vault.

  Demonstrates:
    - a self-signed certificate, for local and test environments
    - a certificate issued by a public CA, renewed automatically
    - importing a certificate you already hold as a PFX

  The import is optional: leave pfxBase64 empty and that resource is skipped, so the sample runs
  as-is.
*/

targetScope = 'local'

@description('The URI of the Key Vault to create the certificates in.')
param vaultUri string

@description('The DNS name to issue certificates for.')
param dnsName string

@description('Addresses notified when a certificate is about to expire or fails to renew.')
param contactEmails string[]

@description('Set to false unless you have a certificate authority account configured. The CA-issued certificate is skipped when false.')
param useCertificateAuthority bool = false

@description('The certificate authority to request certificates from.')
@allowed(['DigiCert', 'GlobalSign', 'OneCertV2-PrivateCA', 'OneCertV2-PublicCA', 'SslAdminV2'])
param certificateAuthority string = 'DigiCert'

@description('The organization ID registered with the certificate authority.')
param certificateAuthorityOrgId string = ''

@description('The account ID registered with the certificate authority.')
param certificateAuthorityAccountId string = ''

@description('The password for the certificate authority account. Must be supplied on every deployment: Key Vault never returns it.')
@secure()
param certificateAuthorityPassword string = ''

@description('A base64-encoded PFX to import. Leave empty to skip the import example.')
@secure()
param pfxBase64 string = ''

@description('The password protecting the PFX, if it has one.')
@secure()
param pfxPassword string = ''

extension keyvault with {
  vaultUri: vaultUri
}

@description('The name the certificate authority account is registered under.')
var issuerName = 'production-ca'

@description('''
Certificate contacts are notified by any EmailContacts lifetime action, and by Key Vault when an
automatic renewal fails. Key Vault keeps a single list per vault, so this resource replaces
whatever is already configured.
''')
resource contacts 'CertificateContacts' = {
  contacts: [
    for email in contactEmails: {
      email: email
    }
  ]
}

@description('''
A self-signed certificate. Fine for development and internal testing; browsers and clients will
not trust it without explicitly importing it.
''')
resource selfSigned 'Certificate' = {
  name: 'dev-${replace(dnsName, '.', '-')}'

  issuer: {
    name: 'Self'
  }

  key: {
    keyType: 'RSA'
    keySize: 2048
    exportable: true
    reuseKey: false
  }

  secret: {
    // PKCS#12 yields a PFX; use application/x-pem-file if you need PEM.
    contentType: 'application/x-pkcs12'
  }

  x509Properties: {
    subject: 'CN=${dnsName}'
    validityInMonths: 12
    keyUsage: ['digitalSignature', 'keyEncipherment']
    ekus: ['1.3.6.1.5.5.7.3.1'] // Server authentication.
    subjectAlternativeNames: {
      dnsNames: [dnsName]
    }
  }

  tags: {
    environment: 'dev'
  }
}

@description('Registers the certificate authority account that issues the production certificate.')
resource issuer 'CertificateIssuer' = if (useCertificateAuthority) {
  name: issuerName
  providerName: certificateAuthority
  orgId: certificateAuthorityOrgId
  accountId: certificateAuthorityAccountId
  password: certificateAuthorityPassword

  admins: [
    for email in contactEmails: {
      emailAddress: email
    }
  ]
}

@description('''
A certificate issued by the registered authority, renewed automatically 30 days before it
expires. Key Vault drives the renewal, so nothing has to run on a schedule.
''')
resource caIssued 'Certificate' = if (useCertificateAuthority) {
  name: 'prod-${replace(dnsName, '.', '-')}'

  // Both resources share the same condition, so the issuer is always present when this is
  // deployed. The dependency is declared explicitly because referencing a conditional resource's
  // properties would otherwise look like it might be null.
  dependsOn: [issuer]

  issuer: {
    name: issuerName
  }

  key: {
    keyType: 'RSA'
    keySize: 2048
    exportable: false
    reuseKey: false
  }

  secret: {
    contentType: 'application/x-pkcs12'
  }

  x509Properties: {
    subject: 'CN=${dnsName}'
    validityInMonths: 12
    keyUsage: ['digitalSignature', 'keyEncipherment']
    ekus: ['1.3.6.1.5.5.7.3.1']
    subjectAlternativeNames: {
      dnsNames: [dnsName]
    }
  }

  lifetimeActions: [
    {
      action: {
        actionType: 'AutoRenew'
      }
      trigger: {
        // Either daysBeforeExpiry or lifetimePercentage, never both.
        daysBeforeExpiry: 30
      }
    }
    {
      action: {
        actionType: 'EmailContacts'
      }
      trigger: {
        lifetimePercentage: 80
      }
    }
  ]

  tags: {
    environment: 'prod'
  }
}

@description('''
Imports a certificate issued elsewhere. An imported certificate carries its own key and validity,
so it cannot also specify policy properties - supply import on its own.
''')
resource imported 'Certificate' = if (!empty(pfxBase64)) {
  name: 'imported-${replace(dnsName, '.', '-')}'

  import: {
    contents: pfxBase64
    password: pfxPassword
  }

  tags: {
    source: 'imported'
  }
}

@description('The SHA-1 thumbprint of the self-signed certificate.')
output selfSignedThumbprint string = selfSigned.thumbprint

@description('When the self-signed certificate expires.')
output selfSignedExpires string = selfSigned.certificateAttributes.expires

@description('''
The Key Vault secret holding the self-signed certificate's private key and chain.
App Service and Application Gateway bind to a URI like this rather than to the certificate itself.
''')
output selfSignedSecretUri string = selfSigned.versionlessSecretId

/*
  Creates the cryptographic keys an application needs: a customer-managed key for encrypting
  data at rest, and a signing key for issuing tokens.

  Demonstrates:
    - RSA and elliptic curve keys, and scoping each to only the operations it needs
    - an automatic rotation policy
    - consuming the generated public key, which never leaves Key Vault in private form
*/

targetScope = 'local'

@description('The URI of the Key Vault to create the keys in, e.g. https://myvault.vault.azure.net/.')
param vaultUri string

@description('Applied as a tag to every key.')
param application string

extension keyvault with {
  vaultUri: vaultUri
}

@description('''
A customer-managed key (CMK) for encrypting data at rest.
Only wrap/unwrap are granted: services encrypt their own data encryption key with this key, and
never use it to encrypt data directly.
''')
resource encryptionKey 'Key' = {
  name: 'cmk-data-at-rest'
  keyType: 'RSA'
  keySize: 3072
  keyOps: ['wrapKey', 'unwrapKey']

  // Rotate automatically well before expiry, and raise an event in time for someone to react if
  // rotation fails.
  rotationPolicy: {
    expireAfter: 'P1Y'
    notifyBeforeExpiry: 'P30D'
    automatic: {
      timeBeforeExpiry: 'P60D'
    }
  }

  tags: {
    application: application
    purpose: 'encryption'
  }
}

@description('''
An elliptic curve key for signing tokens. EC keys are smaller and faster than RSA at an
equivalent strength, which suits high-volume signing.
''')
resource signingKey 'Key' = {
  name: 'jwt-signing-key'
  keyType: 'EC'
  curve: 'P-256'
  keyOps: ['sign', 'verify']

  tags: {
    application: application
    purpose: 'signing'
  }
}

@description('''
Bind Azure services that support customer-managed keys to this version-less URI.
They will then pick up new versions automatically as the rotation policy rotates the key; a
versioned URI would pin them to the key that exists today.
''')
output encryptionKeyUri string = encryptionKey.versionlessId

@description('The current version of the encryption key, for services that require a pinned version.')
output encryptionKeyVersionedUri string = encryptionKey.id

@description('The signing key\'s public half, for verifiers that validate tokens offline.')
output signingPublicKeyPem string = signingKey.publicKeyPem

@description('The same public key in OpenSSH format.')
output signingPublicKeyOpenSsh string = signingKey.publicKeyOpenSsh

/*
  Provisions a signing key in a Managed HSM and grants an application permission to use it.

  Demonstrates:
    - creating an HSM-backed key
    - a rotation policy, which for Managed HSM is a separate resource rather than a key property
    - the Managed HSM's own local RBAC system, which is distinct from Azure RBAC

  A Managed HSM is a dedicated, single-tenant appliance and is billed accordingly. Use the
  'encryption-keys' sample instead if a standard vault meets your requirements.
*/

targetScope = 'local'

@description('The URI of the Managed HSM, e.g. https://myhsm.managedhsm.azure.net/.')
param managedHsmUri string

@description('The object ID of the identity that will use the key, e.g. an application\'s managed identity.')
param principalId string

@description('Applied as a tag to the key.')
param application string

extension keyvault with {
  managedHsmUri: managedHsmUri
}

@description('An HSM-backed signing key. The private key is generated inside the HSM and can never be exported.')
resource signingKey 'ManagedHsmKey' = {
  name: 'payment-signing-key'
  keyType: 'RSA-HSM'
  keySize: 3072
  keyOps: ['sign', 'verify']

  tags: {
    application: application
    purpose: 'signing'
  }
}

@description('''
Rotates the key automatically. Unlike a standard vault key, where rotation is a property of the
key, Managed HSM models the rotation policy as its own resource.
''')
resource rotationPolicy 'ManagedHsmKeyRotationPolicy' = {
  keyName: signingKey.name

  // Must be at least P28D.
  expireAfter: 'P1Y'
  notifyBeforeExpiry: 'P30D'

  // Exactly one of timeBeforeExpiry or timeAfterCreation.
  timeBeforeExpiry: 'P60D'
}

@description('''
A custom role granting only the ability to sign with a key, and to read its public half.
Managed HSM has its own RBAC system: these roles are defined and assigned on the HSM itself, and
are invisible to Azure RBAC.
''')
resource signerRole 'ManagedHsmRoleDefinition' = {
  // Role definitions and assignments are identified by a GUID. Deriving it deterministically
  // keeps the deployment idempotent.
  name: guid(managedHsmUri, 'payment-signer')
  scope: '/keys'
  roleName: 'Payment key signer'
  description: 'Signs payment payloads. Cannot export, delete or re-wrap keys.'

  permissions: [
    {
      dataActions: [
        'Microsoft.KeyVault/managedHsm/keys/sign/action'
        'Microsoft.KeyVault/managedHsm/keys/read/action'
      ]
    }
  ]
}

@description('Grants the application the signing role. Role assignments are immutable: to point one at a different principal, delete it first.')
resource signerAssignment 'ManagedHsmRoleAssignment' = {
  name: guid(managedHsmUri, 'payment-signer', principalId)
  scope: '/keys'
  roleDefinitionId: signerRole.id
  principalId: principalId
}

@description('The version-less key URI. Note that for Managed HSM keys this is "id"; the versioned form is "versionedId".')
output signingKeyUri string = signingKey.id

@description('The current version of the signing key.')
output signingKeyVersionedUri string = signingKey.versionedId

/*
  Replicates a secret across several Key Vaults from a single deployment.

  Demonstrates:
    - overriding the extension's vaultUri on individual resources
    - fanning the same value out to a list of regional vaults

  This is the pattern to reach for when an application runs in several regions and each region
  reads from its own vault, or when you promote configuration from a staging vault to production.
*/

targetScope = 'local'

@description('The vault that acts as the source of truth. Used as the extension default.')
param primaryVaultUri string

@description('Additional vaults to replicate the shared secret into, e.g. one per region.')
param replicaVaultUris string[]

@description('The name of the secret to replicate.')
param secretName string

@description('The value to replicate.')
@secure()
param secretValue string

extension keyvault with {
  // Resources that do not specify their own vaultUri land here.
  vaultUri: primaryVaultUri
}

@description('The authoritative copy, written to the vault configured on the extension.')
resource primary 'Secret' = {
  name: secretName
  value: secretValue
  contentType: 'text/plain'
  tags: {
    role: 'primary'
  }
}

@description('''
A copy in each replica vault. Setting vaultUri on the resource overrides the extension
configuration, so one deployment can span any number of vaults.
''')
resource replicas 'Secret' = [
  for replicaVaultUri in replicaVaultUris: {
    vaultUri: replicaVaultUri
    name: secretName
    value: secretValue
    contentType: 'text/plain'
    tags: {
      role: 'replica'
      replicatedFrom: primaryVaultUri
    }
  }
]

@description('The version-less URI of the authoritative copy.')
output primaryUri string = primary.versionlessId

@description('The version-less URI of each replica.')
output replicaUris array = [for (uri, index) in replicaVaultUris: replicas[index].versionlessId]
